import hashlib
import hmac

import httpx
from cubicle_context import env


def handler(req, ctx):
    secret = env.get("WEBHOOK_SECRET", "")
    target = env.get("RELAY_URL", "")
    if not secret or not target:
        return {"statusCode": 500,
                "body": {"error": "set WEBHOOK_SECRET and RELAY_URL in Global env"}}

    signature = req.header("x-signature", "")
    expected = hmac.new(secret.encode(), req.text().encode(), hashlib.sha256).hexdigest()
    # compare_digest, not ==: the timing of a bytewise comparison leaks
    # how much of the signature was right.
    if not hmac.compare_digest(signature, expected):
        return {"statusCode": 401, "body": {"error": "bad signature"}}

    forwarded = httpx.post(target, json=req.json(), timeout=10)
    ctx.set("last_relayed_status", forwarded.status_code)
    return {"statusCode": 202, "body": {"relayed": forwarded.status_code}}
